function _fnvalidatePdfType(strSomExpFileUpload){
    var objFileUpload = guideBridge.resolveNode(strSomExpFileUpload);
    var allow=objFileUpload.parent.jsonModel.mimeType;
    var fileName=objFileUpload.value;
    var testResult = true;
    if(objFileUpload.value != null){
        var found = allow.find(element => element == fileName.substring(fileName.lastIndexOf(".") + 1));
        /*var found = for (var i = 0; i < allow.length; i++) {
        allow[i] == fileName.substring(fileName.lastIndexOf(".") + 1)
        return false;
        }*/
        if(found==null){
            objFileUpload.validateExpMessage = "The uploaded document is not in "+allow.toString()+" format";
            objFileUpload.value = null;
            testResult=false;
        }else{
            if(validateFileSize(objFileUpload)){
                testResult = true;
            }
            else    {
                testResult = false;
            }
        }
    }
    else{
        testResult = true;
    }
    return testResult;
} 
var isCheck =false;
function validateFileSize(objFileUpload){     
    var isValidated = false;
    var len = objFileUpload.parent.fileList === undefined ? 0 : objFileUpload.parent.fileList.length;
    var totalSize = 0;
    if(len === 0){
        isValidated = true;
    }
    else {
        for(var i = 0;i<len;i++){
            totalSize += objFileUpload.parent.fileList[i][0].files[0].size;
            //totalFileSizes += objFileUpload.parent.fileList[i][0].files[0].size;
        }
        if((totalSize/1024)/1024 <= objFileUpload.parent.fileSizeLimit){
            isValidated = true;
            isCheck = isValidated;
        }         if(isValidated === false){
            objFileUpload.validateExpMessage = "The size of "+objFileUpload.value+" is greater than "+ objFileUpload.parent.fileSizeLimit +" MB."
            objFileUpload.value = null;
        }
    }
    return isValidated;
}
